mapper.select:
select id from ai_service_case_action
where case_id=#{caseId} and actor_kind=#{actorKind} and actor_ref=#{actorRef} and idempotency_key=#{idempotencyKey}
limit 1

mapper.update:
update ai_service_case set state='IN_REVIEW', state_version=state_version+1,
  customer_information_type=#{informationType}, customer_information=#{information},
  public_status=#{publicStatus}, last_public_message=#{publicMessage}, updated_at=now()
where case_id=#{caseId} and member_id=#{memberId} and state_version=#{expectedVersion}
  and state='AWAITING_CUSTOMER_INFORMATION' and customer_information_type=#{informationType}
